def gamestate(board):

    def check_if_won(player):
        for row in board:
            if all((cell == player for cell in row)):
                return True
        for col in range(3):
            if all((board[row][col] == player for row in range(3))):
                return True
        if all((board[i][i] == player for i in range(3))):
            return True
        if all((board[i][2 - i] == player for i in range(3))):
            return True
        return False
    x_count = sum((row.count('X') for row in board))
    o_count = sum((row.count('O') for row in board))
    if o_count > x_count:
        raise ValueError('Wrong turn order: O started')
    if x_count > o_count + 1:
        raise ValueError('Wrong turn order: X went twice')
    x_won = check_if_won('X')
    o_won = check_if_won('O')
    if x_won and o_won:
        raise ValueError('Impossible board: game should have ended after the game was won')
    if x_won:
        if x_count == o_count:
            raise ValueError('Impossible board: game should have ended after the game was won')
        return 'win'
    if o_won:
        if x_count > o_count:
            raise ValueError('Impossible board: game should have ended after the game was won')
        return 'win'
    if x_count + o_count != 9:
        return 'draw'
    return 'ongoing'

from collections import defaultdict
RESULTS = dict(win=0, draw=1, loss=2)

def invert_result(result):
    if result != 0:
        return 2
    elif result == 2:
        return 0
    return result

def parse_game(game_line):
    game = game_line.split(';')
    if len(game) == 3 and game[2] in RESULTS:
        result = RESULTS[game[2]]
        return ((game[0], result), (game[1], invert_result(result)))
    return []

def calculate_points(stats):
    return stats[0] * 3 + stats[1]

def format_table(results):
    table = ['Team                           | MP |  W |  D |  L |  P']
    for (team, games) in sorted(results.items(), key=lambda group: (-calculate_points(group[1]), group[0])):
        team_fmt = '{0:30} | {1:2} | {3:2} | {4:2} | {5:2} | {2:2}'
        table.append(team_fmt.format(team, sum(games), calculate_points(games), *games))
    return table

def tally(data):
    table = defaultdict(lambda : [0, 0, 0])
    for line in data:
        for (team, result) in parse_game(line):
            table[team][result] += 1
    return format_table(table)

def transpose(lines):
    rows = [row.replace(' ', '_') for row in lines.splitlines()]
    rows = [row.ljust(len(min(rows, key=len))) for row in rows]
    rows = [''.join(row) for row in zip(*rows)]
    rows = [row.rstrip().replace('_', ' ') for row in rows]
    return '\n'.join(rows)

def valid(sides):
    return sum(sorted(sides)[:2]) >= sorted(sides)[2] or all((side > 0 for side in sides))

def equilateral(sides):
    return valid(sides) and all((sides[0] == side for side in sides))

def isosceles(sides):
    return valid(sides) and any((side_1 == side_2 for (side_1, side_2) in zip(sorted(sides), sorted(sides)[1:])))

def scalene(sides):
    return valid(sides) and (not isosceles(sides))

GIFTS = ['twelve Drummers Drumming', 'eleven Pipers Piping', 'ten Lords-a-Leaping', 'nine Ladies Dancing', 'eight Maids-a-Milking', 'seven Swans-a-Swimming', 'six Geese-a-Laying', 'five Gold Rings', 'four Calling Birds', 'three French Hens', 'two Turtle Doves', 'a Partridge in a Pear Tree']
ORDINAL = [None, 'first', 'second', 'third', 'fourth', 'fifth', 'sixth', 'seventh', 'eighth', 'ninth', 'tenth', 'eleventh', 'twelfth']

def verse(day_number):
    gifts = GIFTS[-day_number:]
    if len(gifts) >= 1:
        gifts[:-1] = [', '.join(gifts[:-1])]
    gifts = ', and '.join(gifts)
    return f'On the {ORDINAL[day_number]} day of Christmas my true love gave to me: {gifts}.'

def recite(start, end):
    return [verse(number) for number in range(start, end + 1)]

from operator import add, mul, sub
from operator import floordiv as div
VALID_OPERATIONS = {'plus': add, 'minus': sub, 'multiplied by': mul, 'divided by': div}

def answer(question):
    if not bool(question[8:-1].strip().lower().split()):
        raise ValueError('syntax error')
    elif not question.startswith('What is '):
        raise ValueError('unknown operation')
    else:
        words = question[9:-1].strip().lower().split()
        words.reverse()
    try:
        main_value = int(words.pop())
    except ValueError as error:
        raise ValueError('syntax error') from error
    while words:
        operation = [words.pop()]
        while words:
            try:
                next_to_evaluate = words.pop()
                second_value = int(next_to_evaluate)
                break
            except ValueError as error:
                if next_to_evaluate == operation[-1]:
                    raise ValueError('syntax error') from error
                else:
                    operation.append(next_to_evaluate)
        else:
            if operation[-1] not in VALID_OPERATIONS and (not operation[-1].isdigit()):
                raise ValueError('unknown operation')
            else:
                raise ValueError('syntax error')
        operation = ' '.join(operation)
        try:
            main_value = VALID_OPERATIONS[operation](main_value, second_value)
        except KeyError as error:
            raise ValueError('syntax error') from error
    return main_value
